#!/usr/bin/env python3
import hashlib
import os
import tempfile
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

DATA_DIR = "/var/lib/builder/records"


def record_path(record_id: str) -> str:
    digest = hashlib.sha256(record_id.encode("utf-8")).hexdigest()
    return os.path.join(DATA_DIR, digest)


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    server_version = "builder-app"

    def _send(self, status: int, body: bytes = b"", ctype: str = "application/octet-stream"):
        self.send_response(status)
        if body or status == 200:
            self.send_header("Content-Type", ctype)
            self.send_header("Content-Length", str(len(body)))
        else:
            self.send_header("Content-Length", "0")
        self.end_headers()
        if body:
            self.wfile.write(body)

    def _id(self, path: str):
        prefix = "/records/"
        if not path.startswith(prefix):
            return None
        return path[len(prefix):]

    def do_GET(self):
        if self.path == "/health":
            self._send(200, b"ready", "text/plain")
            return
        record_id = self._id(self.path)
        if record_id is None:
            self._send(404)
            return
        try:
            with open(record_path(record_id), "rb") as fh:
                data = fh.read()
        except FileNotFoundError:
            self._send(404)
            return
        self._send(200, data)

    def do_PUT(self):
        record_id = self._id(self.path)
        if record_id is None:
            self._send(404)
            return
        length = self.headers.get("Content-Length")
        if length is None:
            self._send(411)
            return
        try:
            remaining = int(length)
        except ValueError:
            self._send(400)
            return
        chunks = []
        while remaining > 0:
            chunk = self.rfile.read(min(remaining, 1 << 20))
            if not chunk:
                break
            chunks.append(chunk)
            remaining -= len(chunk)
        data = b"".join(chunks)

        target = record_path(record_id)
        fd, tmp = tempfile.mkstemp(dir=DATA_DIR)
        try:
            with os.fdopen(fd, "wb") as fh:
                fh.write(data)
                fh.flush()
                os.fsync(fh.fileno())
            os.replace(tmp, target)
            dir_fd = os.open(DATA_DIR, os.O_RDONLY)
            try:
                os.fsync(dir_fd)
            finally:
                os.close(dir_fd)
        except BaseException:
            try:
                os.unlink(tmp)
            except OSError:
                pass
            raise
        self._send(204)

    def log_message(self, *args):
        pass


def main():
    os.makedirs(DATA_DIR, exist_ok=True)
    server = ThreadingHTTPServer(("0.0.0.0", 8080), Handler)
    server.serve_forever()


if __name__ == "__main__":
    main()
